import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_M": 32, "BLOCK_N": 32, "BLOCK_K": 16, "GROUP_M": 8},
        ),
    ],
    key=["C_IN", "C_out", "OL"],
)
@triton.jit
def _conv_transpose1d_gemm(
    x_ptr,
    w_ptr,
    y_ptr,
    N_batch,
    L_in,
    C_out,
    OL,
    sxn,
    sxl,
    swk,
    swci,
    swco,
    syn,
    syl,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    GROUP_M: tl.constexpr,
    K_SIZE: tl.constexpr,
    C_IN: tl.constexpr,
):
    pid = tl.program_id(0)
    M_total = N_batch * OL
    num_pid_m = tl.cdiv(M_total, BLOCK_M)
    num_pid_n = tl.cdiv(C_out, BLOCK_N)
    num_pid_in_group = GROUP_M * num_pid_n
    group_id = pid // num_pid_in_group
    first_pid_m = group_id * GROUP_M
    group_size_m = tl.minimum(num_pid_m - first_pid_m, GROUP_M)
    pid_in_group = pid % num_pid_in_group
    pid_m = first_pid_m + (pid_in_group % group_size_m)
    pid_n = pid_in_group // group_size_m

    offs_m = pid_m * BLOCK_M + tl.arange(0, BLOCK_M)
    offs_n = pid_n * BLOCK_N + tl.arange(0, BLOCK_N)
    offs_k = tl.arange(0, BLOCK_K)

    n_idx = offs_m // OL
    ol_idx = offs_m % OL

    mask_m = offs_m < M_total
    mask_n = offs_n < C_out

    acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)
    x_base = x_ptr + n_idx * sxn

    for k in range(K_SIZE):
        il = ol_idx - k
        valid = (il >= 0) & (il < L_in) & mask_m
        x_ptrs = x_base + il * sxl

        w_bp = tl.make_block_ptr(
            base=w_ptr + k * swk,
            shape=(C_IN, C_out),
            strides=(swci, swco),
            offsets=(0, pid_n * BLOCK_N),
            block_shape=(BLOCK_K, BLOCK_N),
            order=(1, 0),
        )

        for c0 in range(0, C_IN, BLOCK_K):
            k_idx = c0 + offs_k
            x_tile = tl.load(
                x_ptrs[:, None] + k_idx[None, :],
                mask=valid[:, None] & (k_idx[None, :] < C_IN),
                other=0.0,
            )
            w_tile = tl.load(w_bp, boundary_check=(0, 1), padding_option="zero")
            acc = tl.dot(x_tile, w_tile, acc)
            w_bp = tl.advance(w_bp, (BLOCK_K, 0))

    y_ptrs = y_ptr + n_idx * syn + ol_idx * syl
    tl.store(
        y_ptrs[:, None] + offs_n[None, :],
        acc.to(y_ptr.dtype.element_ty),
        mask=mask_m[:, None] & mask_n[None, :],
    )


class Model(nn.Module):
    def __init__(
        self,
        in_channels,
        out_channels,
        kernel_size,
        stride=1,
        padding=0,
        output_padding=0,
        groups=1,
        bias=False,
    ):
        super(Model, self).__init__()
        self.conv1d_transpose = nn.ConvTranspose1d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            output_padding=output_padding,
            groups=groups,
            bias=bias,
        )
        self._packed = False

    def _pack_weights(self):
        self._w_kio = self.conv1d_transpose.weight.permute(2, 0, 1).contiguous()
        self._K = self.conv1d_transpose.weight.shape[2]
        self._C_out = self.conv1d_transpose.weight.shape[1]
        self._packed = True

    def forward(self, x):
        if not self._packed:
            self._pack_weights()

        B, C_in, L_in = x.shape
        K = self._K
        C_out = self._C_out
        OL = L_in + K - 1

        x_nlc = x.permute(0, 2, 1).contiguous()
        w_kio = self._w_kio
        y_nlc = torch.empty((B, OL, C_out), device=x.device, dtype=x.dtype)

        sxn, sxl, _ = x_nlc.stride()
        swk, swci, swco = w_kio.stride()
        syn, syl, _ = y_nlc.stride()

        M_total = B * OL
        grid = lambda meta: (
            triton.cdiv(M_total, meta["BLOCK_M"]) * triton.cdiv(C_out, meta["BLOCK_N"]),
        )

        _conv_transpose1d_gemm[grid](
            x_nlc,
            w_kio,
            y_nlc,
            B,
            L_in,
            C_out,
            OL,
            sxn,
            sxl,
            swk,
            swci,
            swco,
            syn,
            syl,
            K_SIZE=K,
            C_IN=C_in,
        )

        result = y_nlc.permute(0, 2, 1).contiguous()
        if self.conv1d_transpose.bias is not None:
            result = result + self.conv1d_transpose.bias.view(1, -1, 1)
        return result
